//! The consolidated CDDL schema and validation of CBOR items against it.
//!
//! The schema file is generated by `scripts/extract-cddl.py` from the
//! specification. The `cddl` crate validates against the **first** rule of a
//! document, so a per-vector root is selected by prepending
//! `vector-root = <rule>` to the schema text.

use std::fmt;
use std::path::{Path, PathBuf};

/// Path of the schema file relative to the repository root.
pub const SCHEMA_RELATIVE: &str = "schema/porecatu-remote.cddl";

/// Repository root (this tool lives in `rust/tools/vectors`).
pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..")
}

/// Why the schema could not be used, or an item did not match it.
#[derive(Debug)]
pub enum SchemaError {
    /// The schema file could not be read.
    Read(String),
    /// The schema does not parse as CDDL.
    Parse(String),
    /// The item does not conform to the root rule.
    Invalid(String),
}

impl fmt::Display for SchemaError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SchemaError::Read(e) => write!(f, "cannot read the schema: {e}"),
            SchemaError::Parse(e) => write!(f, "the schema does not parse: {e}"),
            SchemaError::Invalid(e) => write!(f, "does not match the schema: {}", e.trim()),
        }
    }
}

impl std::error::Error for SchemaError {}

/// The schema text, ready to validate items against.
#[derive(Debug, Clone)]
pub struct Schema {
    text: String,
}

impl Schema {
    /// Reads the schema from the repository.
    pub fn load() -> Result<Schema, SchemaError> {
        let path = repo_root().join(SCHEMA_RELATIVE);
        let text = std::fs::read_to_string(&path)
            .map_err(|e| SchemaError::Read(format!("{}: {e}", path.display())))?;
        Schema::from_text(text)
    }

    /// Wraps schema text, checking that it parses.
    pub fn from_text(text: String) -> Result<Schema, SchemaError> {
        cddl::parser::cddl_from_str(&text, false).map_err(SchemaError::Parse)?;
        Ok(Schema { text })
    }

    /// Validates `cbor` against the rule named `root`.
    pub fn validate(&self, root: &str, cbor: &[u8]) -> Result<(), SchemaError> {
        let document = format!("vector-root = {root}\n{}", self.text);
        cddl::validate_cbor_from_slice(&document, cbor, None)
            .map_err(|e| SchemaError::Invalid(e.to_string()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use porecatu_protocol::cbor::{Value, encode};

    fn schema() -> Schema {
        Schema::load().expect("schema loads")
    }

    fn map(entries: Vec<(&str, Value)>) -> Value {
        Value::Map(
            entries
                .into_iter()
                .map(|(k, v)| (k.to_owned(), v))
                .collect(),
        )
    }

    fn hello(extra: Option<(&str, Value)>) -> Vec<u8> {
        let mut entries = vec![
            ("version", Value::Array(vec![Value::Int(0), Value::Int(1)])),
            ("app", Value::Text("porecatu-remote".to_owned())),
            ("app_version", Value::Text("0.1.0".to_owned())),
        ];
        entries.extend(extra);
        encode(&Value::Array(vec![Value::Int(0), map(entries)]))
    }

    #[test]
    fn the_schema_parses() {
        schema();
    }

    #[test]
    fn hello_validates_as_a_message() {
        schema().validate("message", &hello(None)).unwrap();
    }

    #[test]
    fn unknown_key_is_accepted() {
        let bytes = hello(Some(("zzz", Value::Int(1))));
        schema().validate("message", &bytes).unwrap();
    }

    #[test]
    fn missing_required_key_is_rejected() {
        let bytes = encode(&Value::Array(vec![
            Value::Int(0),
            map(vec![("app", Value::Text("x".to_owned()))]),
        ]));
        assert!(schema().validate("message", &bytes).is_err());
    }

    #[test]
    fn wrong_type_is_rejected() {
        let bytes = encode(&Value::Array(vec![
            Value::Int(3),
            map(vec![("reason", Value::Text("normal".to_owned()))]),
        ]));
        assert!(schema().validate("message", &bytes).is_err());
    }

    #[test]
    fn envelopes_validate() {
        let nonce = Value::Array(vec![Value::Int(0), Value::Bytes(vec![7; 32])]);
        schema().validate("host-envelope", &encode(&nonce)).unwrap();
        let short = Value::Array(vec![Value::Int(0), Value::Bytes(vec![7; 31])]);
        assert!(schema().validate("host-envelope", &encode(&short)).is_err());
        let data = Value::Array(vec![Value::Int(16), Value::Bytes(vec![1, 2, 3])]);
        schema()
            .validate("client-envelope", &encode(&data))
            .unwrap();
        let unavailable = Value::Array(vec![Value::Int(17)]);
        schema()
            .validate("client-envelope", &encode(&unavailable))
            .unwrap();
        let closed_bad = Value::Array(vec![Value::Int(18), Value::Int(6)]);
        assert!(
            schema()
                .validate("client-envelope", &encode(&closed_bad))
                .is_err()
        );
    }

    #[test]
    fn handshake_start_and_pair_request_validate() {
        let start = Value::Array(vec![Value::Int(1), Value::Bytes(vec![0; 48])]);
        schema()
            .validate("handshake-start", &encode(&start))
            .unwrap();
        let bad_kind = Value::Array(vec![Value::Int(2), Value::Bytes(vec![0; 48])]);
        assert!(
            schema()
                .validate("handshake-start", &encode(&bad_kind))
                .is_err()
        );
        let request = map(vec![
            ("token", Value::Bytes(vec![9; 16])),
            ("device", Value::Text("Pixel".to_owned())),
            ("platform", Value::Int(0)),
        ]);
        schema()
            .validate("pair-request", &encode(&request))
            .unwrap();
    }

    #[test]
    fn broken_schema_text_is_a_parse_error() {
        assert!(matches!(
            Schema::from_text("a = [".to_owned()),
            Err(SchemaError::Parse(_))
        ));
    }
}
